mapper.select:
SELECT T.* , (SELECT X.CMMNS_CD_VALUE_NM FROM SAC100 X WHERE X.CMMNS_CD_ID = (CASE WHEN T.RCPT_RQST_COURS_SE_CD != '99' THEN 'RCPT_RQST_COURS_SE_CD' WHEN T.RCPT_RQST_COURS_SE_CD = '99' THEN 'RCPT_RQST_COURS_LCLAS_SE_CD' ELSE 'RCPT_RQST_COURS_SE_CD' END ) AND X.CMMNS_CD_VALUE = T.RCPT_RQST_COURS_SE_CD) AS RCPT_RQST_COURS_SE_NM /* 접수의뢰경로구분명*/ FROM ( SELECT /* YOO.CHI.HOON isry.itgcm.casemng.uneart.TrprInqMapper.selectTrprInqList(대상자목록조회) */ #{TOT_CNT} TOT_CNT , ROWNUM AS SEQ , TT1.* FROM ( SELECT /*+ INDEX_DESC(T1 SEA200_PK)*/ T1.TRPR_INFO_NO AS TRPR_INFO_NO -- 대상자정보번호(TR) , T1.INDV_IDNTFC_NO AS INDV_IDNTFC_NO -- 개인식별번호 , T2.RRNO_ENCPT AS RRNO -- 주민등록번호 , T1.UNT_TASKWK_SE_CD AS UNT_TASKWK_SE_CD -- 단위업무구분코드 , C##RG.DEC_B64(T1.TRPR_NM_ENCPT) AS TRPR_NM -- 대상자명 , T1.TRPR_BRTH_YMD AS TRPR_BRTH_YMD -- 대상자출생일자 , T1.SXDC_SE_CD AS SXDC_SE_CD -- 성별구분코드 , T1.MRG_YN AS MRG_YN -- 결혼여부 , T1.TRPR_TELNO AS TRPR_TELNO -- 전화번호 , C##RG.DEC_B64(T1.MBL_TELNO_ENCPT)AS MBL_TELNO -- 휴대전화번호 , C##RG.DEC_B64(T1.EML_ADDR_ENCPT)AS EML_ADDR -- 이메일주소 , T1.SNS_SE_CD AS SNS_SE_CD -- SNS구분코드 , C##RG.DEC_B64(T1.MSNGR_ID_ENCPT) AS MSNGR_ID -- 메신저아이디 , T1.ZIP AS ZIP -- 우편번호 , T1.PST_ADDR AS PST_ADDR -- 우편주소 , T1.DADDR AS DADDR -- 상세주소 , T1.ACBG_SE_CD AS ACBG_SE_CD -- 학력구분코드 , T1.GRDTN_STTS_SE_CD AS GRDTN_STTS_SE_CD -- 졸업상태구분코드 , T1.GRADE_SE_CD AS GRADE_SE_CD -- 학년구분코드 , C##RG.DEC_B64(T1.PSPT_ENG_FLNM_ENCPT) AS PSPT_ENG_FLNM -- 여권영문성명 , T1.TRPR_BCRN_TYPE_SE_CD AS TRPR_BCRN_TYPE_SE_CD -- 대상자배경유형구분코드 , T1.TRPR_BCRN_TYPE_RM_NM AS TRPR_BCRN_TYPE_RM_NM -- 대상자배경유형비고명 , T1.NLTY_NTN_SE_CD AS NLTY_NTN_SE_CD -- 국적국가구분코드 , T1.ENTCNY_YMD AS ENTCNY_YMD -- 입국일자 , T1.BRTH_NTN_SE_CD AS BRTH_NTN_SE_CD -- 출생국가구분코드 , T1.GROWTH_NTN_SE_CD AS GROWTH_NTN_SE_CD -- 성장국가구분코드 , T1.VISA_TYPE_SE_CD AS VISA_TYPE_SE_CD -- 비자유형구분코드 , T1.HANAWO_PENU_NO AS HANAWO_PENU_NO -- 하나원기수번호 , T1.RELGN_SE_CD AS RELGN_SE_CD -- 종교구분코드 , T1.QLFC_INFO_MNG_NO AS QLFC_INFO_MNG_NO -- 자격정보관리번호 , T1.RCPT_PIC_NO AS RCPT_PIC_NO -- 접수담당자번호 , C##RG.DEC_B64(T4.FLNM_ENCPT) AS RCPT_PIC_NM -- 접수담당자명 , T1.RCPT_INST_NO AS RCPT_INST_NO -- 접수기관번호 , T3.INST_NM AS RCPT_INST_NM -- 접수기관명 , T1.CASE_TRPR_TYPE_SE_CD AS CASE_TRPR_TYPE_SE_CD -- 사례대상자유형구분코드 , T1.CASE_MNG_SE_CD AS CASE_MNG_SE_CD -- 사례관리구분코드 , T1.CASE_TRPR_SLCTN_YMD AS CASE_TRPR_SLCTN_YMD -- 사례대상자선정일자 , T1.CASE_TRPR_UNSL_CS_CN AS CASE_TRPR_UNSL_CS_CN -- 사례대상자미선정사유내용 , C##RG.DEC_B64(T1.PRTCR_NM_ENCPT) AS PRTCR_NM_ENCPT -- 보호자명암호화 , T1.TRPR_REL_SE_CD AS TRPR_REL_SE_CD -- 대상자관계구분코드 , T1.LIVTGT_YN AS LIVTGT_YN -- 동거여부 , T1.PRTCR_AGRE_YN AS PRTCR_AGRE_YN -- 보호자동의여부 , T1.PRVC_PVSN_AGRE_YN AS PRVC_PVSN_AGRE_YN -- 개인정보제공동의여부 , T1.SRVC_CTRT_AGRE_YN AS SRVC_CTRT_AGRE_YN -- 서비스계약동의여부 , T1.TAG_NO AS TAG_NO -- 태그번호 , T1.TAG_NM AS TAG_NM -- 태그명 , T1.CASE_TRPR_NOAP_CS_SE_CD AS CASE_TRPR_NOAP_CS_SE_CD -- 사례대상자미신청사유구분코드 , T1.PRTCR_TELNO AS PRTCR_TELNO -- 보호자전화번호 , C##RG.DEC_B64(T1.PRTCR_MBL_TELNO_ENCPT) AS PRTCR_MBL_TELNO_ENCPT -- 보호자휴대전화번호 , C##RG.DEC_B64(T1.PRTCR_EML_ADDR_ENCPT) AS PRTCR_EML_ADDR_ENCPT -- 보호자이메일주소 , T1.PRTCR_ZIP AS PRTCR_ZIP -- 보호자우편번호 , T1.PRTCR_PST_ADDR AS PRTCR_PST_ADDR -- 보호자우편주소 , T1.PRTCR_DADDR AS PRTCR_DADDR -- 보호자상세주소 , T1.PRTCR_BRTH_YMD AS PRTCR_BRTH_YMD /* 보호자출생일자*/ , T1.RESDN_SHAPE_SE_CD AS RESDN_SHAPE_SE_CD -- 거주형태구분코드 , T1.RESIDE_SHAPE_SE_CD AS RESIDE_SHAPE_SE_CD -- 주거형태구분코드 , T1.RESIDE_SHAPE_ETC_CN AS RESIDE_SHAPE_ETC_CN -- 주거형태기타내용 , T1.FAM_CHAR_SE_CD AS FAM_CHAR_SE_CD -- 가족특성구분코드 , T1.INDV_IDNTFC_INFO_UNIPT_CS_CN AS INDV_IDNTFC_INFO_UNIPT_CS_CN -- 개인식별정보미입력사유내용 , T1.INDV_IDNTFC_CRTR_YMD AS INDV_IDNTFC_CRTR_YMD -- 개인식별기준일자 , T1.TRPR_PHOTO_ATFINO AS TRPR_PHOTO_ATFINO /* 대상자사진 첨부파일번호*/ , T1.ATFINO AS ATFINO /* 첨부파일번호*/ , T1.RCPT_RQST_COURS_SE_CD AS RCPT_RQST_COURS_SE_CD /* 접수의뢰경로구분코드*/ , T1.RCPT_RQST_COURS_DTL_INST_NM AS RCPT_RQST_COURS_DTL_INST_NM /* 접수의뢰경로구분코드*/ , T1.FAM_SHAPE_SE_CD AS FAM_SHAPE_SE_CD /* 가족형태구분코드*/ , T1.FAM_SHAPE_ETC_CN AS FAM_SHAPE_ETC_CN /* 가족형태기타내용*/ , T1.FAM_CHAR_ETC_CN AS FAM_CHAR_ETC_CN /* 가족특성기타내용*/ , T1.PRVC_AGRE_YMD AS PRVC_AGRE_YMD /* 개인정보동의일자*/ , T1.TRPR_REL_ETC_CN AS TRPR_REL_ETC_CN /* 대상자관계기타내용*/ , T1.FAM_REL_SE_CD AS FAM_REL_SE_CD /* 가족관계구분코드*/ , T1.FAM_REL_SE_ETC_CN AS FAM_REL_SE_ETC_CN /* 가족관계구분기타내용*/ , T1.FAM_CHAR_SE_CD_NM AS FAM_CHAR_SE_CD_NM /* 가족특성구분코드명*/ , T1.FRST_RGTR_ID AS FRST_RGTR_ID -- 최초등록자아이디 , T1.FRST_REG_DT AS FRST_REG_DT -- 최초등록일시 , T1.LAST_MDFR_ID AS LAST_MDFR_ID -- 최종수정자아이디 , T1.LAST_MDFCN_DT AS LAST_MDFCN_DT -- 최종수정일시 , T1.ORGNL_REQSTD_MNG_NO AS ORGNL_REQSTD_MNG_NO -- 원본신청관리번호 FROM SEA200 T1 /* 대상자정보 */ , SCA300 T2 /* 개인정보 */ , SAA000 T3 /* 통합기관*/ , SCA100 T4 /* 종사자*/ WHERE 1 = 1 AND T1.INDV_IDNTFC_NO = T2.INDV_IDNTFC_NO (+) -- 개인식별번호 AND T1.RCPT_INST_NO = T3.INST_NO -- 접수담당자기관번호 AND T1.RCPT_PIC_NO = T4.ENFSN_NO (+) -- 종사자번호 AND T1.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} -- 단위업무구분코드 AND T1.DEL_YN = 'N' /* 삭제여부*/ AND T1.FRST_REG_DT BETWEEN TO_DATE(#{REG_BGNG_YMD} || '000000', 'YYYYMMDDHH24MISS') -- 등록시작일자 AND TO_DATE(#{REG_END_YMD} || '235959', 'YYYYMMDDHH24MISS') -- 등록종료일자
) TT1 ) T WHERE 1 = 1
AND T.SEQ >= #{START_IDX} AND T.SEQ <= #{LAST_IDX}

/* 대상자등록여부 조회*/
 SELECT COUNT(TRPR_INFO_NO) AS TRPR_CNT
   FROM SEA200
  WHERE 1 = 1
    AND DEL_YN = 'N'
    AND TRPR_INFO_NO = #{TRPR_INFO_NO}

/* 복지부 연계된건은 삭제 불가입니다*/
/* 서비스의뢰접수결과(서비스의뢰접수결과 CAB110, 서비스의뢰요청 CAB120*/
    SELECT /* isry.itgcm.casemng.uneart.TrprInqMapper.selectlinkMohwSrvcRqstTrpr(복지부연계) 업무공통 YOO.CHI.HOON*/ 
           COUNT(T22.TRPR_INFO_NO)              AS LINK_MOHW_CNT                    /* 대상자번호*/  
      FROM CAB110 T33 INNER JOIN /* 복지부연계(서비스의뢰접수결과)*/
           SEA200 T22 /* 대상자정보*/
        ON (T33.SRV_RQST_PRCS_ID /* 서비스의뢰처리ID*/  = T22.LINK_ADDTNG_DATAA_VALUE1) /* 연계추가컬럼1*/
     WHERE 1 = 1
       AND T22.TRPR_INFO_NO = #{TRPR_INFO_NO}

/* 내부연계된건은 삭제 불가입니다*/
   SELECT COUNT(A.RCPT_TRPR_INFO_NO) AS EXISTS_CNT 
   FROM SEB420 A
   WHERE A.RCPT_TRPR_INFO_NO = #{TRPR_INFO_NO}

SELECT NVL(MAX(MNG_SN)+1,1)  AS MNG_SN
  FROM SEA210
 WHERE TRPR_INFO_NO = #{TRPR_INFO_NO}

SELECT NVL(MAX(MNG_SN)+1,1)  AS MNG_SN
  FROM SEA230
 WHERE TRPR_INFO_NO = #{TRPR_INFO_NO}

SELECT NVL(MAX(MNG_SN)+1,1)  AS MNG_SN
  FROM SEA240
 WHERE TRPR_INFO_NO = #{TRPR_INFO_NO}

SELECT NVL(MAX(MNG_SN)+1,1)  AS MNG_SN
  FROM SEA250
 WHERE TRPR_INFO_NO = #{TRPR_INFO_NO}

         /*selectTrprCaseDpcnInq - Yoo ChiHoon*/               
	 SELECT COUNT(TRPR_INFO_NO) AS TRPR_CNT
	   FROM SEB100 
	  WHERE TRPR_INFO_NO     = #{TRPR_INFO_NO}
	    AND UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD}


/* isry.itgcm.casemng.uneart.TrprInqMapper.selectSggCd(지역코드로 시군구코드 구하기) */                   
SELECT             
    SUBSTR(SGG_CD,0,2) AS SGG_CD
FROM SAA020 /* 시군구코드 */
WHERE 1=1
 AND CTPV_SE_CD = #{SGG_CD}

        /* isry.itgcm.casemng.uneart.TrprInqMapper.selectCaseCnt */
        SELECT COUNT(1) AS CASE_CNT
		FROM SEB100 A, SEA200 B
		WHERE A.CASE_PRGRS_STTS_SE_CD IN ('01','02','03','12','10') /* 사례등록, 서비스계획, 서비스실행, 종결신청, 재개입 */
		  AND A.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD}
		  AND A.TRPR_INFO_NO = B.TRPR_INFO_NO
		  AND B.INDV_IDNTFC_NO = #{INDV_IDNTFC_NO}
